export const PACK_LESSONS: Lesson[] = PACKS.flatMap((p) =>
  p.lessons.map((l, i) => ({
    id: `${p.id}-p${i + 1}`,
    title: l.t,
    subtitle: p.name,
    emoji: p.emoji,
    kind: "words" as const,
    items: l.w.map(([mn, en], j) => ({
      id: `w${j + 1}`,
      show: mn,
      say: transliterate(mn).toLowerCase(),
      hint: "",
      emoji: p.emoji,
      trick: "",
      meaning: en,
    })),
  })),
);

export const PACK_GROUPS = [...new Set(PACKS.map((p) => p.group))];
